const D = { amount:.6, reach:.42, hue:32, energy:.7, speed:1, sat:38, style:'luminance', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, u = Math.min(W, H), cx = W/2, cy = H/2;
const dg = drawingContext;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
const clamp = (v,a,b) => v < a ? a : v > b ? b : v;

// --- kick: beat + bass, floored by continuous real-time breathing so it never
// re-phases exactly at t+8s (8s = 16 beats at cps .5 would otherwise realign) ---
const beatKick = clamp(K.pulse*.7 + A.bass*.9, 0, 1.4);
const breathe  = .5 + .5*Math.sin(K.t*1.27);           // real-time floor
const secGain  = .45 + .55*(K.intensity==null?.6:K.intensity);
let amt = P.amount * (0.20 + 0.80*beatKick) * (0.55 + 0.45*breathe) * secGain;
amt = clamp(amt, 0, 1);

const reach = clamp(P.reach, .08, .85);
const rot   = K.t*0.16 * P.speed;                       // continuous aurora drift
const maxR  = Math.hypot(W, H) * 0.5;
const r0    = maxR * (1 - reach);
const style = P.style;

noStroke();

// ---------- edge-weighted vignette pass (partial frame: center stays clear) ----------
function radialFill(stops, mode){
  blendMode(mode);
  const g = dg.createRadialGradient(cx, cy, r0*0.55, cx, cy, maxR*1.05);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  dg.save(); dg.fillStyle = g; dg.fillRect(0,0,W,H); dg.restore();
}

if (style === 'ritual') {
  // inverse: darkness closes in from the edges on the beat — austere / menacing
  const a = clamp(amt*0.92, 0, 0.95);
  radialFill([[0,'rgba(0,0,0,0)'],[0.6,'rgba(0,0,0,'+(a*0.3).toFixed(3)+')'],[1,'hsla('+((P.hue+220)%360)+',60%,4%,'+a.toFixed(3)+')']], MULTIPLY);
} else if (style === 'thermal') {
  const a = clamp(amt, 0, 0.9);
  radialFill([[0,'rgba(0,0,0,0)'],[0.45,'hsla(230,80%,40%,'+(a*0.35).toFixed(3)+')'],[0.8,'hsla(30,95%,55%,'+(a*0.8).toFixed(3)+')'],[1,'hsla(55,90%,92%,'+a.toFixed(3)+')']], ADD);
} else if (style === 'signal') {
  const a = clamp(amt*0.7, 0, 0.8);
  const o = u*0.012*(1+beatKick);
  blendMode(ADD);
  [[ -o,0,'0,100%,55%'],[o*0.5,-o,'120,100%,55%'],[0,o,'240,100%,60%']].forEach(c=>{
    const g = dg.createRadialGradient(cx+c[0],cy+c[1], r0*0.55, cx+c[0],cy+c[1], maxR*1.05);
    g.addColorStop(0,'hsla('+c[2]+',0)'); g.addColorStop(1,'hsla('+c[2].replace(/[^,]+$/,'')+a.toFixed(3)+')');
    dg.save(); dg.fillStyle=g; dg.fillRect(0,0,W,H); dg.restore();
  });
} else if (style === 'bars') {
  // horizontal light bars scanning vertically — geometric, non-radial
  blendMode(ADD);
  const nb = 5, a = clamp(amt, 0, 0.85);
  for (let i=0;i<nb;i++){
    const y = ((fr(i)*H + (K.t*40*P.speed + i*H/nb)) % (H+80)) - 40;
    const bh = u*(0.02+0.05*fr(i+3))*(0.6+0.8*amt);
    const g = dg.createLinearGradient(0,y-bh,0,y+bh);
    const col = (P.hue + i*20)%360;
    g.addColorStop(0,'hsla('+col+',60%,80%,0)');
    g.addColorStop(0.5,'hsla('+col+',55%,88%,'+(a*(0.4+0.6*beatKick)).toFixed(3)+')');
    g.addColorStop(1,'hsla('+col+',60%,80%,0)');
    dg.save(); dg.fillStyle=g; dg.fillRect(0,y-bh,W,bh*2); dg.restore();
  }
} else {
  // luminance (default): warm near-white bloom hugging the frame edge
  const a = clamp(amt*0.9, 0, 0.9);
  radialFill([[0,'rgba(0,0,0,0)'],[0.7,'hsla('+P.hue+','+P.sat+'%,86%,'+(a*0.35).toFixed(3)+')'],[1,'hsla('+P.hue+','+Math.max(10,P.sat-15)+'%,92%,'+a.toFixed(3)+')']], ADD);
}

// ---------- aurora floor: seeded blobs orbiting the frame edge (always moving) ----------
if (style !== 'ritual') {
  blendMode(ADD);
  const na = 7;
  for (let i=0;i<na;i++){
    const sp  = 0.25 + fr(i)*0.9;
    const ang = rot*sp + fr(i+9)*6.283;
    const rr  = u*(0.44 + 0.05*Math.sin(K.t*0.7 + i));
    const ex  = cx + Math.cos(ang)*rr*1.34;
    const ey  = cy + Math.sin(ang)*rr*1.02;
    const flare = 0.35 + 0.65*beatKick + 0.3*Math.sin(K.t*1.1 + i*1.7);
    const sz  = u*(0.09 + 0.06*flare) * (0.5 + 0.9*P.energy) * (0.5 + 0.6*amt);
    let hh, ss = 62, bb = 92;
    if (style === 'thermal') { hh = clamp(30 + 220*(1-flare), 0, 360); ss = 90; }
    else if (style === 'signal') { hh = [0,120,240][i%3]; ss = 90; }
    else hh = (P.hue + i*13 + K.t*6) % 360;
    for (let r=3;r>=1;r--){
      fill(hh, ss, bb, 5*flare*r);
      circle(ex, ey, sz*r*0.55);
    }
  }
}

blendMode(BLEND);
dg.shadowBlur = 0;
